{"thought": "The current app.js file is mostly correct, but it needs to handle the operation summary and error messages properly. I'll update the summary function and error handling.", "action": "write_file", "path": "static/app.js", "content": "const list = document.getElementById("list");
const count = document.getElementById("count");
const errorBox = document.getElementById("error");
const ORDER = ["a", "operation", "b", "result"];  // how a row reads: the values the user entered, then the computed ones
const INPUTS = 3;

function summary(item) {
  const parts = ORDER.map((f) => (typeof item[f] === "number" ? UI.num(item[f]) : UI.symbol(item[f])));
  parts.splice(INPUTS, 0, "=");
  return parts.join(" ");
}

async function clearAll() {
  await fetch("/api/calculations", { method: "DELETE" });
  UI.toast("Cleared", "success");
  await load();
}

async function load() {
  UI.loading(list);
  const res = await fetch("/api/calculations");
  const data = await res.json();
  let shown = data.items;
  count.textContent = shown.length + " " + "calculations";
  UI.renderList(list, shown.map((i) => ({ ...i, summary: summary(i) })), (item) => ({
    title: "summary",
    badges: ["operation"],
  }), "Nothing here yet. Add the first one above.");
}

async function calculate() {
  errorBox.textContent = "";
  const a = parseFloat(document.getElementById("a").value);
  const b = parseFloat(document.getElementById("b").value);
  const operation = document.getElementById("operation").value;
  if (operation === "divide" && b === 0) {
    errorBox.textContent = "Division by zero";
    return;
  }
  const res = await fetch("/api/calculations", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ a, b, operation })
  });
  const data = await res.json();
  if (!res.ok) {
    errorBox.textContent = typeof data.detail === "string" ? data.detail : "Please check your input";
    return;
  }
  UI.toast("Added", "success");
  await load();
}

document.getElementById("form").addEventListener("submit", (ev) => {
  ev.preventDefault();
  calculate();
});
document.getElementById("clear").addEventListener("click", clearAll);

load();"}

